L["Reset to defaults"] = "Restaurar padrões"
L["Left-click: show/hide the GPS"] = "Clique esquerdo: mostrar/ocultar o GPS"
L["Right-click: options"] = "Botão direito: opções"
L["Drag: move this button"] = "Arrastar: mover este botão"
L["Car-GPS style map and navigation. Settings are in the AzerothGPS window."] = "Mapa e navegação no estilo GPS de carro. As configurações ficam na janela do AzerothGPS."
L["Open AzerothGPS options"] = "Abrir opções do AzerothGPS"
L["Name"] = "Nome"
L["Choose an icon:"] = "Escolha um ícone:"
L["Saved at logout or /reload"] = "Salvo ao desconectar ou com /reload"
L["Floor: %s"] = "Andar: %s"
L["Floor: every floor here"] = "Andar: todos os andares aqui"
L["Icons %d-%d of %d (mouse wheel scrolls)"] = "Ícones %d-%d de %d (a roda do mouse rola)"
L["pinned %s (double-click it for a stop, right-click to remove it)"] = "%s marcado (clique duplo para criar uma parada, botão direito para remover)"
L["%d of your drawn roads and walls are in the map data now (kept in your saved data)"] = "%d das suas estradas e muros desenhados agora estão nos dados do mapa (guardados nos seus dados salvos)"
L["recorded %d flight nodes for map %d"] = "%d pontos de voo registrados para o mapa %d"
L["flight %s took %.0fs"] = "o voo %s levou %.0fs"
L["your Hearthstone"] = "sua Pedra de Regresso"
L["Teleport: %s"] = "Teleportar: %s"
L["%s ready again: the route is worked out again with it."] = "%s disponível de novo: a rota foi recalculada com ela."
L["Make a U-turn"] = "Faça o retorno"
L["Make a U-turn now"] = "Faça o retorno agora"
L["make a U-turn"] = "faça o retorno"
L["Sharp left"] = "Curva fechada à esquerda"
