L["With the GPS map as your minimap, a double-click on the logo sends the map back to its corner instead."] = "Com o mapa do GPS como minimapa, um clique duplo no logotipo manda o mapa de volta para o canto."
L["The GPS map as your minimap"] = "O mapa do GPS como minimapa"
L["Minimap replacement"] = "Substituto do minimapa"
