L["As a macro it's one step a press."] = "Como macro, é um passo por toque."
L["/agps pad select|yes|remove|back|recenter | menu | zoom in|out | pan up|down|left|right  (the controller's controls, for macros)"] = "/agps pad select|yes|remove|back|recenter | menu | zoom in|out | pan up|down|left|right  (os controles do controle, para macros)"
L["Map menu"] = "Menu do mapa"
L["Options"] = "Opções"
