L["Mark corners around the nodes to farm: %s adds one at the crosshair  ·  %s: undo  ·  %s: finish  |cff9d9d9d(%s cancels)|r"] = "Marque cantos ao redor dos nós para farmar: %s adiciona um na mira  ·  %s: desfazer  ·  %s: concluir  |cff9d9d9d(%s cancela)|r"
L["Mark points at the crosshair with %s  ·  %s: undo  ·  %s: finish  |cff9d9d9d(%s cancels)|r"] = "Marque pontos na mira com %s  ·  %s: desfazer  ·  %s: concluir  |cff9d9d9d(%s cancela)|r"
L["Mark more corners first."] = "Marque mais cantos primeiro."
L["Move the map and press %s to mark each corner of a loop around nodes, %s to undo one, and %s (or %s on the first corner) to finish: the route visits every known node inside that's shown (herbs, ore or both), round and round (the nearest 60 at most). %s cancels."] = "Mova o mapa e pressione %s para marcar cada canto de um circuito ao redor dos nós, %s para desfazer um e %s (ou %s no primeiro canto) para concluir: a rota visita cada nó conhecido mostrado dentro (ervas, minérios ou ambos), dando voltas (no máximo os 60 mais próximos). %s cancela."
L["%s: Add Corner   %s: Undo Corner   %s: Finish Area   %s: Cancel   %s: Zoom   %s: Pan"] = "%s: Adicionar canto   %s: Desfazer canto   %s: Concluir área   %s: Cancelar   %s: Zoom   %s: Mover"
L["Add Corner"] = "Adicionar canto"
L["Undo Corner"] = "Desfazer canto"
