L["Import From GatherMate2"] = "Importar do GatherMate2"
L["Adds the herbs and mines GatherMate2 knows to your own, and every one GatherMate2_Data lists when it's installed, shown faded until you gather there. It glows when there are some you haven't imported. (Shown with GatherMate2 installed)"] = "Adiciona aos seus as ervas e os veios que o GatherMate2 conhece, e todos os que o GatherMate2_Data lista quando está instalado, mostrados esmaecidos até você coletar lá. Brilha quando há algum que você não importou. (Mostrado com o GatherMate2 instalado)"
L["Imported %s herbs and %s mines, %s already known."] = "Importadas %s ervas e %s veios, %s já conhecidos."
L["GatherMate2 has no herbs or mines to import."] = "O GatherMate2 não tem ervas nem veios para importar."
L["Importing from GatherMate2: %d%%"] = "Importando do GatherMate2: %d%%"
L["GatherMate2 has herbs or mines you haven't imported."] = "O GatherMate2 tem ervas ou veios que você não importou."
L["Remove Unconfirmed Herbs and Ore"] = "Remover ervas e minérios não confirmados"
L["Removes the herbs and ore you imported (from GatherMate2 or a list) and haven't gathered yet. The ones you gathered stay. You're asked first."] = "Remove as ervas e os minérios que você importou (do GatherMate2 ou de uma lista) e ainda não coletou. Os que você coletou ficam. Você é perguntado antes."
L["Removed %s unconfirmed herbs and ore."] = "%s ervas e minérios não confirmados removidos."
L["Remove %s unconfirmed herbs and ore? These are the ones imported that you haven't gathered yet; the ones you gathered stay. This can't be undone."] = "Remover %s ervas e minérios não confirmados? São os importados que você ainda não coletou; os que você coletou ficam. Não dá para desfazer."
L["Requires Mining %d"] = "Requer Mineração %d"
L["Requires Herbalism %d"] = "Requer Herborismo %d"
L["Available"] = "Disponíveis"
